{
  "PROP-legion-backe-inv-023": {
    "property_id": "PROP-legion-backe-inv-023",
    "audit_result": {
      "property_id": "PROP-legion-backe-inv-023",
      "classification": "potential-vulnerability",
      "code_path": "src/sales/LegionAbstractSale.sol::setAcceptedCapital::L436-442",
      "proof_trace": "`setAcceptedCapital` (L436-442) stores the caller-supplied `merkleRoot` directly into `s_saleStatus.acceptedCapitalMerkleRoot` with no `!= bytes32(0)` guard; passing zero is syntactically valid. When the root is zero, `_verifyCanClaimExcessCapital` (L767) always fails `MerkleProofLib.verify` (no leaf hash can equal 0), reverting every `withdrawExcessInvestedCapital` call with a misleading `CannotWithdrawExcessInvestedCapital` error and DoSing excess-capital withdrawal for all investors.",
      "attack_scenario": "A Legion admin (or a compromised Legion key) calls `setAcceptedCapital(bytes32(0))`; all subsequent `withdrawExcessInvestedCapital` calls revert at the Merkle check, locking investors' entitled excess capital until the root is explicitly corrected \u2014 during which any time-bounded refund window may expire.",
      "checklist_id": "PROP-legion-backe-inv-023"
    },
    "text": "OpenApp setAcceptedCapital Merkle root must not be zero when used for excess withdrawal.",
    "assertion": "withdrawExcess_OA() => acceptedCapitalMerkleRoot != bytes32(0)",
    "covers": "SG-006",
    "severity": "HIGH",
    "type": "invariant"
  }
}

